import{_ as d,a0 as i,w as g,s as p,ao as l,I as n,x as e,a1 as s,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"使用 Docker 和 Kubernetes 将 MongoDB 作为微服务运行 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Docker 和 Kubernetes 将 MongoDB 作为微服务运行 | LCTT (201709) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Docker 和 Kubernetes 将 MongoDB 作为微服务运行 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Docker 和 Kubernetes 将 MongoDB 作为微服务运行 | LCTT (201709) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201709/20160404 Running MongoDB as a Microservice with Docker and Kubernetes","title":"使用 Docker 和 Kubernetes 将 MongoDB 作为微服务运行","tag":"201709","desc":""},"relativePath":"201709/20160404 Running MongoDB as a Microservice with Docker and Kubernetes.md","filePath":"[post].md"}'),m={name:"201709/20160404 Running MongoDB as a Microservice with Docker and Kubernetes.md"};function u(b,o,a,D,M,B){const t=i("Link");return g(),p("div",null,[o[44]||(o[44]=l('<h1 id="使用-docker-和-kubernetes-将-mongodb-作为微服务运行" tabindex="-1">使用 Docker 和 Kubernetes 将 MongoDB 作为微服务运行 <a class="header-anchor" href="#使用-docker-和-kubernetes-将-mongodb-作为微服务运行" aria-label="Permalink to “使用 Docker 和 Kubernetes 将 MongoDB 作为微服务运行”">​</a></h1><h3 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to “介绍”">​</a></h3><p><img src="https://webassets.mongodb.com/_com_assets/cms/bigstock-cargo-containers-96277130-377cd07c2b.jpg" alt=""></p><p>想在笔记本电脑上尝试 MongoDB？只需执行一个命令，你就会有一个轻量级的、独立的沙箱。完成后可以删除你所做的所有痕迹。</p><p>想在多个环境中使用相同的<ruby>程序栈<rt>application stack</rt></ruby>副本？构建你自己的容器镜像，让你的开发、测试、运维和支持团队使用相同的环境克隆。</p><p>容器正在彻底改变整个软件生命周期：从最早的技术性实验和概念证明，贯穿了开发、测试、部署和支持。</p><p>编排工具用来管理如何创建、升级多个容器，并使之高可用。编排还控制容器如何连接，以从多个微服务容器构建复杂的应用程序。</p><p>丰富的功能、简单的工具和强大的 API 使容器和编排功能成为 DevOps 团队的首选，将其集成到连续集成（CI） 和连续交付 （CD） 的工作流程中。</p><p>这篇文章探讨了在容器中运行和编排 MongoDB 时遇到的额外挑战，并说明了如何克服这些挑战。</p><h3 id="mongodb-的注意事项" tabindex="-1">MongoDB 的注意事项 <a class="header-anchor" href="#mongodb-的注意事项" aria-label="Permalink to “MongoDB 的注意事项”">​</a></h3><p>使用容器和编排运行 MongoDB 有一些额外的注意事项：</p>',11)),n("ul",null,[o[9]||(o[9]=n("li",null,[e("MongoDB 数据库节点是有状态的。如果容器发生故障并被重新编排，数据则会丢失（能够从副本集的其他节点恢复，但这需要时间），这是不合需要的。为了解决这个问题，可以使用诸如 Kubernetes 中的"),n("ruby",null,[e("数据卷"),n("rt",null,"volume")]),e(" 抽象等功能来将容器中临时的 MongoDB 数据目录映射到持久位置，以便数据在容器故障和重新编排过程中存留。")],-1)),o[10]||(o[10]=n("li",null,"一个副本集中的 MongoDB 数据库节点必须能够相互通信 - 包括重新编排后。副本集中的所有节点必须知道其所有对等节点的地址，但是当重新编排容器时，可能会使用不同的 IP 地址重新启动。例如，Kubernetes Pod 中的所有容器共享一个 IP 地址，当重新编排 pod 时，IP 地址会发生变化。使用 Kubernetes，可以通过将 Kubernetes 服务与每个 MongoDB 节点相关联来处理，该节点使用 Kubernetes DNS 服务提供“主机名”，以保持服务在重新编排中保持不变。",-1)),o[11]||(o[11]=n("li",null,[e("一旦每个单独的 MongoDB 节点运行起来（每个都在自己的容器中），则必须初始化副本集，并添加每个节点到其中。这可能需要在编排工具之外提供一些额外的处理。具体来说，必须使用目标副本集中的一个 MongoDB 节点来执行 "),n("code",null,"rs.initiate"),e(" 和 "),n("code",null,"rs.add"),e(" 命令。")],-1)),o[12]||(o[12]=n("li",null,"如果编排框架提供了容器的自动化重新编排（如 Kubernetes），那么这将增加 MongoDB 的弹性，因为这可以自动重新创建失败的副本集成员，从而在没有人为干预的情况下恢复完全的冗余级别。",-1)),n("li",null,[o[4]||(o[4]=e("应该注意的是，虽然编排框架可能监控容器的状态，但是不太可能监视容器内运行的应用程序或备份其数据。这意味着使用 ",-1)),s(t,{href:"https://www.mongodb.com/products/mongodb-enterprise-advanced"},{default:r(()=>[...o[0]||(o[0]=[e("MongoDB Enterprise Advanced",-1)])]),_:1}),o[5]||(o[5]=e(" 和 ",-1)),s(t,{href:"https://www.mongodb.com/products/mongodb-professional"},{default:r(()=>[...o[1]||(o[1]=[e("MongoDB Professional",-1)])]),_:1}),o[6]||(o[6]=e(" 中包含的 ",-1)),s(t,{href:"https://www.mongodb.com/cloud/"},{default:r(()=>[...o[2]||(o[2]=[e("MongoDB Cloud Manager",-1)])]),_:1}),o[7]||(o[7]=e(" 等强大的监控和备份解决方案非常重要。可以考虑创建自己的镜像，其中包含你首选的 MongoDB 版本和 ",-1)),s(t,{href:"https://docs.cloud.mongodb.com/tutorial/nav/install-automation-agent/"},{default:r(()=>[...o[3]||(o[3]=[e("MongoDB Automation Agent",-1)])]),_:1}),o[8]||(o[8]=e("。",-1))])]),o[45]||(o[45]=n("h3",{id:"使用-docker-和-kubernetes-实现-mongodb-副本集",tabindex:"-1"},[e("使用 Docker 和 Kubernetes 实现 MongoDB 副本集 "),n("a",{class:"header-anchor",href:"#使用-docker-和-kubernetes-实现-mongodb-副本集","aria-label":"Permalink to “使用 Docker 和 Kubernetes 实现 MongoDB 副本集”"},"​")],-1)),o[46]||(o[46]=n("p",null,"如上节所述，分布式数据库（如 MongoDB）在使用编排框架（如 Kubernetes）进行部署时，需要稍加注意。本节将介绍详细介绍如何实现。",-1)),o[47]||(o[47]=n("p",null,"我们首先在单个 Kubernetes 集群中创建整个 MongoDB 副本集（通常在一个数据中心内，这显然不能提供地理冗余）。实际上，很少有必要改变成跨多个集群运行，这些步骤将在后面描述。",-1)),o[48]||(o[48]=n("p",null,"副本集的每个成员将作为自己的 pod 运行，并提供一个公开 IP 地址和端口的服务。这个“固定”的 IP 地址非常重要，因为外部应用程序和其他副本集成员都可以依赖于它在重新编排 pod 的情况下保持不变。",-1)),o[49]||(o[49]=n("p",null,"下图说明了其中一个 pod 以及相关的复制控制器和服务。",-1)),o[50]||(o[50]=n("p",null,[n("img",{src:"https://webassets.mongodb.com/_com_assets/cms/image04-0b13b8ba36.png",alt:""})],-1)),o[51]||(o[51]=n("p",null,[n("em",null,"图 1：MongoDB 副本集成员被配置为 Kubernetes Pod 并作为服务公开")],-1)),o[52]||(o[52]=n("p",null,"逐步介绍该配置中描述的资源：",-1)),n("ul",null,[n("li",null,[o[14]||(o[14]=e("从核心开始，有一个名为 ",-1)),o[15]||(o[15]=n("code",null,"mongo-node1",-1)),o[16]||(o[16]=e(" 的容器。",-1)),o[17]||(o[17]=n("code",null,"mongo-node1",-1)),o[18]||(o[18]=e(" 包含一个名为 ",-1)),o[19]||(o[19]=n("code",null,"mongo",-1)),o[20]||(o[20]=e(" 的镜像，这是一个在 ",-1)),s(t,{href:"https://hub.docker.com/_/mongo/"},{default:r(()=>[...o[13]||(o[13]=[e("Docker Hub",-1)])]),_:1}),o[21]||(o[21]=e(" 上托管的一个公开可用的 MongoDB 容器镜像。容器在集群中暴露端口 ",-1)),o[22]||(o[22]=n("code",null,"27107",-1)),o[23]||(o[23]=e("。",-1))]),o[24]||(o[24]=l("<li>Kubernetes 的数据卷功能用于将连接器中的 <code>/data/db</code> 目录映射到名为 <code>mongo-persistent-storage1</code> 的永久存储上，这又被映射到在 Google Cloud 中创建的名为 <code>mongodb-disk1</code> 的磁盘中。这是 MongoDB 存储其数据的地方，这样它可以在容器重新编排后保留。</li><li>容器保存在一个 pod 中，该 pod 中有标签命名为 <code>mongo-node</code>，并提供一个名为 <code>rod</code> 的（任意）示例。</li><li>配置 <code>mongo-node1</code> 复制控制器以确保 <code>mongo-node1</code> pod 的单个实例始终运行。</li><li>名为 <code>mongo-svc-a</code> 的 <code>负载均衡</code> 服务给外部开放了一个 IP 地址以及 <code>27017</code> 端口，它被映射到容器相同的端口号上。该服务使用选择器来匹配 pod 标签来确定正确的 pod。外部 IP 地址和端口将用于应用程序以及副本集成员之间的通信。每个容器也有本地 IP 地址，但是当容器移动或重新启动时，这些 IP 地址会变化，因此不会用于副本集。</li>",4))]),o[53]||(o[53]=l('<p>下一个图显示了副本集的第二个成员的配置。</p><p><img src="https://webassets.mongodb.com/_com_assets/cms/image00-f5bc4ecaf8.png" alt=""></p><p><em>图 2：第二个 MongoDB 副本集成员配置为 Kubernetes Pod</em></p><p>90％ 的配置是一样的，只有这些变化：</p><ul><li>磁盘和卷名必须是唯一的，因此使用的是 <code>mongodb-disk2</code> 和 <code>mongo-persistent-storage2</code></li><li>Pod 被分配了一个 <code>instance: jane</code> 和 <code>name: mongo-node2</code> 的标签，以便新的服务可以使用选择器与图 1 所示的 <code>rod</code> Pod 相区分。</li><li>复制控制器命名为 <code>mongo-rc2</code></li><li>该服务名为<code> mongo-svc-b</code>，并获得了一个唯一的外部 IP 地址（在这种情况下，Kubernetes 分配了 <code>104.1.4.5</code>）</li></ul><p>第三个副本成员的配置遵循相同的模式，下图展示了完整的副本集：</p><p><img src="https://webassets.mongodb.com/_com_assets/cms/image01-b1896be8f6.png" alt=""></p><p><em>图 3：配置为 Kubernetes 服务的完整副本集成员</em></p><p>请注意，即使在三个或更多节点的 Kubernetes 群集上运行图 3 所示的配置，Kubernetes 可能（并且经常会）在同一主机上编排两个或多个 MongoDB 副本集成员。这是因为 Kubernetes 将三个 pod 视为属于三个独立的服务。</p><p>为了在区域内增加冗余，可以创建一个附加的 <em>headless</em> 服务。新服务不向外界提供任何功能（甚至不会有 IP 地址），但是它可以让 Kubernetes 通知三个 MongoDB pod 形成一个服务，所以 Kubernetes 会尝试在不同的节点上编排它们。</p><p><img src="https://webassets.mongodb.com/_com_assets/cms/image02-5769db88c4.png" alt=""></p><p><em>图 4：避免同一 MongoDB 副本集成员的 Headless 服务</em></p>',12)),n("p",null,[o[26]||(o[26]=e("配置和启动 MongoDB 副本集所需的实际配置文件和命令可以在白皮书《",-1)),s(t,{href:"https://www.mongodb.com/collateral/microservices-containers-and-orchestration-explained"},{default:r(()=>[...o[25]||(o[25]=[e("启用微服务：阐述容器和编排",-1)])]),_:1}),o[27]||(o[27]=e("》中找到。特别的是，需要一些本文中描述的特殊步骤来将三个 MongoDB 实例组合成具备功能的、健壮的副本集。",-1))]),o[54]||(o[54]=l('<h4 id="多个可用区域-mongodb-副本集" tabindex="-1">多个可用区域 MongoDB 副本集 <a class="header-anchor" href="#多个可用区域-mongodb-副本集" aria-label="Permalink to “多个可用区域 MongoDB 副本集”">​</a></h4><p>上面创建的副本集存在风险，因为所有内容都在相同的 GCE 集群中运行，因此都在相同的<ruby>可用区<rt>availability zone</rt></ruby>中。如果有一个重大事件使可用区离线，那么 MongoDB 副本集将不可用。如果需要地理冗余，则三个 pod 应该在三个不同的可用区或地区中运行。</p><p>令人惊奇的是，为了创建在三个区域之间分割的类似的副本集（需要三个集群），几乎不需要改变。每个集群都需要自己的 Kubernetes YAML 文件，该文件仅为该副本集中的一个成员定义了 pod、复制控制器和服务。那么为每个区域创建一个集群，永久存储和 MongoDB 节点是一件很简单的事情。</p><p><img src="https://webassets.mongodb.com/_com_assets/cms/image03-d16cbbfe42.png" alt=""></p><p><em>图 5：在多个可用区域上运行的副本集</em></p><h3 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h3>',6)),n("p",null,[o[29]||(o[29]=e("要了解有关容器和编排的更多信息 - 所涉及的技术和所提供的业务优势 - 请阅读白皮书《",-1)),s(t,{href:"https://www.mongodb.com/collateral/microservices-containers-and-orchestration-explained"},{default:r(()=>[...o[28]||(o[28]=[e("启用微服务：阐述容器和编排",-1)])]),_:1}),o[30]||(o[30]=e("》。该文件提供了获取本文中描述的副本集，并在 Google Container Engine 中的 Docker 和 Kubernetes 上运行的完整的说明。",-1))]),o[55]||(o[55]=n("hr",null,null,-1)),o[56]||(o[56]=n("p",null,"作者简介：",-1)),o[57]||(o[57]=n("p",null,"Andrew 是 MongoDB 的产品营销总经理。他在去年夏天离开 Oracle 加入 MongoDB，在 Oracle 他花了 6 年多的时间在产品管理上，专注于高可用性。他可以通过 @andrewmorgan 或者在他的博客（clusterdb.com）评论联系他。",-1)),o[58]||(o[58]=n("hr",null,null,-1)),n("p",null,[o[32]||(o[32]=e("via: ",-1)),s(t,{href:"https://www.mongodb.com/blog/post/running-mongodb-as-a-microservice-with-docker-and-kubernetes"},{default:r(()=>[...o[31]||(o[31]=[e("https://www.mongodb.com/blog/post/running-mongodb-as-a-microservice-with-docker-and-kubernetes",-1)])]),_:1})]),n("p",null,[o[36]||(o[36]=e("作者：",-1)),s(t,{href:"http://www.clusterdb.com/"},{default:r(()=>[...o[33]||(o[33]=[e("Andrew Morgan",-1)])]),_:1}),o[37]||(o[37]=e(" 译者：",-1)),s(t,{href:"https://github.com/geekpi"},{default:r(()=>[...o[34]||(o[34]=[e("geekpi",-1)])]),_:1}),o[38]||(o[38]=e(" 校对：",-1)),s(t,{href:"https://github.com/wxy"},{default:r(()=>[...o[35]||(o[35]=[e("wxy",-1)])]),_:1})]),n("p",null,[o[41]||(o[41]=e("本文由 ",-1)),s(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...o[39]||(o[39]=[e("LCTT",-1)])]),_:1}),o[42]||(o[42]=e(" 原创编译，",-1)),s(t,{href:"https://linux.cn/"},{default:r(()=>[...o[40]||(o[40]=[e("Linux中国",-1)])]),_:1}),o[43]||(o[43]=e(" 荣誉推出",-1))])])}const T=d(m,[["render",u]]);export{w as __pageData,T as default};
